type SemVer = {
    major: number;
    minor: number;
    patch: number;
    prerelease: string[]; // empty array means no prerelease
};

function parseSemVer(v: string): SemVer {
    // Strip build metadata
    const plusIdx = v.indexOf('+');
    if (plusIdx !== -1) v = v.slice(0, plusIdx);

    // Split prerelease
    const hyphenIdx = v.indexOf('-');
    let core = v;
    let prereleasePart = '';
    if (hyphenIdx !== -1) {
        core = v.slice(0, hyphenIdx);
        prereleasePart = v.slice(hyphenIdx + 1);
    }

    const coreParts = core.split('.');
    if (coreParts.length !== 3) throw new Error(`Invalid version core: ${v}`);

    const [majorStr, minorStr, patchStr] = coreParts;
    const major = parseNumericIdentifier(majorStr, 'major');
    const minor = parseNumericIdentifier(minorStr, 'minor');
    const patch = parseNumericIdentifier(patchStr, 'patch');

    const prerelease = prereleasePart
        ? prereleasePart.split('.').map(id => validatePrereleaseIdentifier(id))
        : [];

    return { major, minor, patch, prerelease };
}

function parseNumericIdentifier(str: string, name: string): number {
    if (!/^\d+$/.test(str)) throw new Error(`Invalid numeric ${name}: ${str}`);
    if (str.length > 1 && str.startsWith('0')) throw new Error(`Leading zero in ${name}: ${str}`);
    const num = Number(str);
    if (!Number.isSafeInteger(num)) throw new Error(`Numeric ${name} out of range: ${str}`);
    return num;
}

function validatePrereleaseIdentifier(id: string): string {
    if (id.length === 0) throw new Error('Empty prerelease identifier');
    if (!/^[0-9A-Za-z-]+$/.test(id)) throw new Error(`Invalid prerelease identifier: ${id}`);
    // numeric identifiers must not have leading zeros
    if (/^\d+$/.test(id) && id.length > 1 && id.startsWith('0')) {
        throw new Error(`Leading zero in numeric prerelease identifier: ${id}`);
    }
    return id;
}

function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
    const aNum = /^\d+$/.test(a);
    const bNum = /^\d+$/.test(b);

    if (aNum && bNum) {
        const diff = Number(a) - Number(b);
        return diff < 0 ? -1 : diff > 0 ? 1 : 0;
    }
    if (aNum && !bNum) return -1; // numeric < alphanumeric
    if (!aNum && bNum) return 1;  // alphanumeric > numeric

    // both alphanumeric: lexical ASCII order
    return a < b ? -1 : a > b ? 1 : 0;
}

export function compareSemver(a: string, b: string): -1 | 0 | 1 {
    const av = parseSemVer(a);
    const bv = parseSemVer(b);

    if (av.major !== bv.major) return av.major < bv.major ? -1 : 1;
    if (av.minor !== bv.minor) return av.minor < bv.minor ? -1 : 1;
    if (av.patch !== bv.patch) return av.patch < bv.patch ? -1 : 1;

    const aPre = av.prerelease;
    const bPre = bv.prerelease;

    // No prerelease vs prerelease
    if (aPre.length === 0 && bPre.length === 0) return 0;
    if (aPre.length === 0) return 1; // a is release, higher
    if (bPre.length === 0) return -1; // b is release, higher

    // Both have prerelease: compare identifier by identifier
    const len = Math.max(aPre.length, bPre.length);
    for (let i = 0; i < len; i++) {
        const aId = aPre[i];
        const bId = bPre[i];
        if (aId === undefined) return -1; // a has fewer identifiers -> lower precedence
        if (bId === undefined) return 1;  // b has fewer identifiers -> lower precedence
        const cmp = compareIdentifiers(aId, bId);
        if (cmp !== 0) return cmp;
    }

    return 0;
}
