function buildOrder(deps: Record<string, string[]>): string[] {
    // Collect all nodes
    const nodes = new Set<string>();
    for (const pkg of Object.keys(deps)) {
        nodes.add(pkg);
        for (const dep of deps[pkg]) nodes.add(dep);
    }

    // Build adjacency (reverse edges) and indegree map
    const adj = new Map<string, string[]>(); // node -> list of dependents
    const indegree = new Map<string, number>();
    for (const node of nodes) {
        adj.set(node, []);
        indegree.set(node, 0);
    }

    for (const [pkg, depList] of Object.entries(deps)) {
        for (const dep of depList) {
            // edge dep -> pkg
            adj.get(dep)!.push(pkg);
            indegree.set(pkg, indegree.get(pkg)! + 1);
        }
    }

    // Simple binary min-heap for strings
    class MinHeap {
        private data: string[] = [];
        private less(a: string, b: string): boolean { return a < b; }

        push(item: string) {
            this.data.push(item);
            this.bubbleUp(this.data.length - 1);
        }

        pop(): string | undefined {
            if (this.data.length === 0) return undefined;
            const top = this.data[0];
            const end = this.data.pop()!;
            if (this.data.length > 0) {
                this.data[0] = end;
                this.sinkDown(0);
            }
            return top;
        }

        size(): number { return this.data.length; }

        private bubbleUp(idx: number) {
            const element = this.data[idx];
            while (idx > 0) {
                const parentIdx = Math.floor((idx - 1) / 2);
                const parent = this.data[parentIdx];
                if (!this.less(element, parent)) break;
                this.data[parentIdx] = element;
                this.data[idx] = parent;
                idx = parentIdx;
            }
        }

        private sinkDown(idx: number) {
            const length = this.data.length;
            const element = this.data[idx];
            while (true) {
                let leftIdx = 2 * idx + 1;
                let rightIdx = 2 * idx + 2;
                let swapIdx: number | null = null;

                if (leftIdx < length) {
                    const left = this.data[leftIdx];
                    if (this.less(left, element)) swapIdx = leftIdx;
                }
                if (rightIdx < length) {
                    const right = this.data[rightIdx];
                    if (
                        (swapIdx === null && this.less(right, element)) ||
                        (swapIdx !== null && this.less(right, this.data[swapIdx]))
                    ) {
                        swapIdx = rightIdx;
                    }
                }
                if (swapIdx === null) break;
                this.data[idx] = this.data[swapIdx];
                this.data[swapIdx] = element;
                idx = swapIdx;
            }
        }
    }

    const heap = new MinHeap();
    for (const [node, deg] of indegree.entries()) {
        if (deg === 0) heap.push(node);
    }

    const result: string[] = [];
    while (heap.size() > 0) {
        const cur = heap.pop()!;
        result.push(cur);
        for (const neighbor of adj.get(cur)!) {
            indegree.set(neighbor, indegree.get(neighbor)! - 1);
            if (indegree.get(neighbor) === 0) heap.push(neighbor);
        }
    }

    if (result.length !== nodes.size) {
        throw new Error("cycle");
    }
    return result;
}
