function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let field = "";
  let i = 0;
  const len = line.length;
  let inQuotes = false;

  while (i < len) {
    const ch = line[i];

    if (inQuotes) {
      if (ch === '"') {
        // possible escaped quote or closing quote
        if (i + 1 < len && line[i + 1] === '"') {
          field += '"';
          i += 2; // skip both quotes
        } else {
          // closing quote
          inQuotes = false;
          i++; // move past the closing quote
          // after a closing quote only a comma or end of line is allowed
          if (i < len && line[i] !== ",") {
            throw new Error("Invalid character after closing quote");
          }
        }
      } else {
        field += ch;
        i++;
      }
    } else {
      if (ch === ",") {
        fields.push(field);
        field = "";
        i++;
      } else if (ch === '"') {
        // start of a quoted field; only allowed at the beginning of a field
        if (field.length !== 0) {
          // quote inside an unquoted field – treat as literal per lenient handling
          field += ch;
          i++;
        } else {
          inQuotes = true;
          i++;
        }
      } else {
        field += ch;
        i++;
      }
    }
  }

  if (inQuotes) {
    throw new Error("Unterminated quoted field");
  }

  // push the final field (handles trailing commas as empty fields)
  fields.push(field);
  return fields;
}
