export function slugify(s: string): string {
  // Normalize to NFD to separate accents from letters
  const normalized = s.normalize('NFD');
  // Remove diacritic marks
  const withoutDiacritics = normalized.replace(/\p{Diacritic}/gu, '');
  // Convert to lower case
  const lower = withoutDiacritics.toLowerCase();
  // Replace any sequence of non-alphanumeric characters with a hyphen
  const hyphenated = lower.replace(/[^a-z0-9]+/g, '-');
  // Trim leading/trailing hyphens
  const trimmed = hyphenated.replace(/^[-]+|[-]+$/g, '');
  return trimmed;
}

