export function parseDuration(input: string): number {
    if (!input) {
        throw new Error('Invalid duration');
    }

    const unitOrder: Record<string, number> = { h: 0, m: 1, s: 2 };
    const seen: Set<string> = new Set();
    let lastOrder = -1;
    let totalSeconds = 0;

    const regex = /(\d+)([hms])/g;
    let match: RegExpExecArray | null;
    let consumed = 0;

    while ((match = regex.exec(input)) !== null) {
        const [full, numStr, unit] = match;
        consumed += full.length;

        if (seen.has(unit)) {
            throw new Error('Invalid duration');
        }
        seen.add(unit);

        const order = unitOrder[unit];
        if (order < lastOrder) {
            throw new Error('Invalid duration');
        }
        lastOrder = order;

        const value = Number(numStr);
        if (!Number.isInteger(value) || value < 0) {
            throw new Error('Invalid duration');
        }

        switch (unit) {
            case 'h':
                totalSeconds += value * 3600;
                break;
            case 'm':
                totalSeconds += value * 60;
                break;
            case 's':
                totalSeconds += value;
                break;
        }
    }

    if (consumed !== input.length) {
        // some characters were not matched (e.g., spaces or unknown units)
        throw new Error('Invalid duration');
    }

    if (seen.size === 0) {
        throw new Error('Invalid duration');
    }

    return totalSeconds;
}
