export function buildOrder(deps: Record<string, string[]>): string[] {
    // Build set of all nodes
    const nodes = new Set<string>();
    for (const pkg of Object.keys(deps)) nodes.add(pkg);
    for (const depList of Object.values(deps)) {
        for (const d of depList) nodes.add(d);
    }

    // adjacency list: from a node to the set of nodes that depend on it
    const adj = new Map<string, Set<string>>();
    // indegree count for each node
    const indeg = new Map<string, number>();
    for (const n of nodes) {
        adj.set(n, new Set());
        indeg.set(n, 0);
    }

    // Populate graph
    for (const [pkg, depList] of Object.entries(deps)) {
        const uniq = new Set(depList); // avoid duplicate edges
        for (const d of uniq) {
            // edge d -> pkg
            adj.get(d)!.add(pkg);
            indeg.set(pkg, (indeg.get(pkg) ?? 0) + 1);
        }
    }

    // Kahn's algorithm with lexicographically smallest choice
    const zero: string[] = [];
    for (const [node, deg] of indeg.entries()) {
        if (deg === 0) zero.push(node);
    }
    zero.sort(); // smallest first

    const result: string[] = [];

    while (zero.length) {
        const cur = zero.shift()!; // smallest available
        result.push(cur);
        for (const nxt of adj.get(cur)!) {
            const newDeg = (indeg.get(nxt) ?? 0) - 1;
            indeg.set(nxt, newDeg);
            if (newDeg === 0) {
                // insert while keeping array sorted
                const idx = binarySearchInsertPos(zero, nxt);
                zero.splice(idx, 0, nxt);
            }
        }
    }

    if (result.length !== nodes.size) {
        throw new Error("cycle detected");
    }
    return result;
}

// binary search to find insertion index to keep array sorted ascending
function binarySearchInsertPos(arr: string[], value: string): number {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (arr[mid] < value) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}
