function parseCsvLine(line: string): string[] {
    const fields: string[] = [];
    let field = "";
    let i = 0;
    const len = line.length;
    let inQuotes = false;

    while (i < len) {
        const ch = line[i];

        if (inQuotes) {
            if (ch === '"') {
                // Look ahead for escaped quote
                if (i + 1 < len && line[i + 1] === '"') {
                    field += '"';
                    i += 2;
                    continue;
                } else {
                    // End of quoted field
                    inQuotes = false;
                    i++; // consume closing quote
                    // After closing quote, next char must be comma or end
                    if (i < len && line[i] !== ',') {
                        throw new Error("Invalid character after closing quote");
                    }
                    continue;
                }
            } else {
                field += ch;
                i++;
                continue;
            }
        } else {
            if (ch === ',') {
                fields.push(field);
                field = "";
                i++;
                continue;
            } else if (ch === '"') {
                if (field.length !== 0) {
                    // Quote not at start of field -> error per RFC
                    throw new Error("Unexpected quote in unquoted field");
                }
                inQuotes = true;
                i++;
                continue;
            } else {
                field += ch;
                i++;
                continue;
            }
        }
    }

    if (inQuotes) {
        throw new Error("Unterminated quoted field");
    }

    // Push the final field (including case of empty line -> one empty field)
    fields.push(field);
    return fields;
}
